### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

// 功能函数：一维滚动 DP 求最长公共子串
string lcsSubstring(const string& a, const string& b) {
    int m = (int)b.size();
    vector<int> dp(m + 1, 0); // dp[j]：以 b[j-1] 结尾的公共后缀长度（当前行）
    int bestLen = 0, endPos = 0; // 记录最大长度及其在 a 中的结束位置

    for (int i = 1; i <= (int)a.size(); ++i) {
        char c = a[i - 1];
        // 从右往左更新，确保 dp[j-1] 仍是上一行的值
        for (int j = m; j >= 1; --j) {
            if (c == b[j - 1]) {
                dp[j] = dp[j - 1] + 1;
                if (dp[j] > bestLen) {
                    bestLen = dp[j];
                    endPos = i;
                }
            } else {
                dp[j] = 0;
            }
        }
    }
    return a.substr(endPos - bestLen, bestLen);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 按题意：替换字符 + 输入流
    string all, line;
    while (getline(cin, line)) {
        all += line;
        all += '\n';
    }
    // 将引号和逗号替换为空格，然后流式读取两个字符串
    for (char &ch : all) {
        if (ch == '\"' || ch == ',') ch = ' ';
    }
    stringstream ss(all);
    string str1, str2;
    ss >> str1 >> str2;

    string ans = lcsSubstring(str1, str2);
    cout << "\"" << ans << "\""; // 按样例输出带引号
    return 0;
}
